"use client";
// @zeus-internal
import { ArrowRight } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion, type Variants } from "motion/react";
import { useState } from "react";
import { ArtemisButton, ArtemisButtonLink } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import { HEADING_LINES, STORIES, type UseCaseStory } from "./05-shader-spotlight/data";
import { SceneShader } from "./05-shader-spotlight/scene-shader";
const BADGE_HIDDEN = { opacity: 0, filter: "blur(5px)", y: 8 };
const INTRO_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 10 };
const SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
interface WordReveal {
    order: number;
    reduce: boolean;
}
const WORD_VARIANTS: Variants = {
    hidden: { opacity: 0, filter: "blur(10px)", y: "24%" },
    visible: ({ order, reduce }: WordReveal) => reduce
        ? { opacity: 1, transition: { duration: 0 } }
        : { opacity: 1, filter: "blur(0px)", y: "0%", transition: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay: order * 0.06 } },
};
const INSTANT = { duration: 0 };
const CARD_ENTER = { opacity: 0, filter: "blur(8px)", y: 10 };
const CARD_TRANSITION = { duration: 0.42, ease: ARTEMIS_EASE_OUT };
const SCENE_TRANSITION = { duration: 0.55, ease: ARTEMIS_EASE_OUT };
const OPTION_BASE = "art:h-auto art:font-normal art:hover:bg-transparent art:hover:text-inherit art:group art:flex art:min-h-32 art:flex-1 art:items-start art:gap-4 art:p-4 art:text-left art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-inset art:@min-[640px]/artemis:p-5";
const LINE_OFFSETS = HEADING_LINES.map((_, i) => HEADING_LINES.slice(0, i).reduce((sum, line) => sum + line.length, 0));
function Heading({ reduce }: {
    reduce: boolean;
}) {
    return (<motion.h2 className="art:block art:mt-7 art:text-balance art:tracking-[-0.05em] art:text-4xl art:font-medium" initial="hidden" whileInView="visible" viewport={{ once: true, amount: 0.4 }}>
      {HEADING_LINES.map((line, lineIndex) => (<span key={line.join(" ")} className="art:block">
          {line.map((word, i) => (<motion.span key={word} className="art:inline-block art:will-change-transform" variants={WORD_VARIANTS} custom={{ order: LINE_OFFSETS[lineIndex] + i, reduce } satisfies WordReveal}>
              {word}
              {i < line.length - 1 ? <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">&nbsp;</span> : null}
            </motion.span>))}
        </span>))}
    </motion.h2>);
}
function StoryOption({ story, active, onSelect }: {
    story: UseCaseStory;
    active: boolean;
    onSelect: () => void;
}) {
    const Icon = story.icon;
    return (<ArtemisButton variant="link" size="none" aria-pressed={active} onClick={onSelect} className={artemisCx(OPTION_BASE, active ? "art:bg-muted/70 art:text-foreground" : "art:text-muted-foreground art:hover:text-foreground")}>
      <span className={artemisCx("art:mt-0.5 art:grid art:size-10 art:shrink-0 art:place-items-center art:rounded-full art:transition-colors", active ? "art:bg-foreground art:text-background" : "art:bg-muted art:text-muted-foreground")}>
        <Icon className="art:size-4" strokeWidth={1.7} aria-hidden="true"/>
      </span>
      <span className="art:min-w-0">
        <span className="art:block art:font-medium art:text-sm">{story.label}</span>
        <span className="art:mt-2 art:block art:text-pretty art:text-xs art:leading-5 art:opacity-70">{story.summary}</span>
      </span>
    </ArtemisButton>);
}
export default function UseCasesShaderSpotlight() {
    const reduce = useReducedMotion() ?? false;
    const [activeId, setActiveId] = useState(STORIES[0].id);
    const story = STORIES.find((s) => s.id === activeId) ?? STORIES[0];
    return (<section className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div className="art:mx-auto art:max-w-3xl art:text-center">
          <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={BADGE_HIDDEN} whileInView={reduce ? undefined : SHOWN} viewport={{ once: true, margin: "-50px" }} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
            Use cases
          </motion.span>
          <Heading reduce={reduce}/>
          <motion.p className="art:mx-auto art:mt-6 art:max-w-2xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7" initial={INTRO_HIDDEN} whileInView={reduce ? undefined : SHOWN} viewport={{ once: true, margin: "-60px" }} transition={{ duration: 0.5, delay: 0.26, ease: ARTEMIS_EASE_OUT }}>
            Choose the moment your team is facing now. Each story shows how a calmer foundation can change the quality of
            what happens next.
          </motion.p>
        </div>

        <div className="art:mt-14 art:grid art:gap-4 art:@min-[640px]/artemis:mt-16 art:@min-[1024px]/artemis:grid-cols-[1.25fr_0.75fr] art:@min-[1024px]/artemis:gap-5">
          <div className="art:relative art:min-h-[29rem] art:overflow-hidden art:rounded-3xl art:@min-[640px]/artemis:min-h-[34rem]">
            <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0">
              <AnimatePresence initial={false}>
                <motion.div key={story.id} className="art:absolute art:inset-0" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={reduce ? INSTANT : SCENE_TRANSITION}>
                  <SceneShader scene={story.id}/>
                </motion.div>
              </AnimatePresence>
            </div>
            <div className="art:absolute art:inset-0 art:bg-background/10 art:dark:bg-background/42"/>
            <div aria-live="polite" className="art:absolute art:inset-x-4 art:bottom-4 art:@min-[640px]/artemis:inset-x-6 art:@min-[640px]/artemis:bottom-6">
              <AnimatePresence mode="wait" initial={false}>
                <motion.div key={story.id} className="art:rounded-3xl art:border art:border-border/60 art:bg-background/78 art:p-5 art:backdrop-blur-xl art:@min-[640px]/artemis:max-w-xl art:@min-[640px]/artemis:p-7" initial={reduce ? false : CARD_ENTER} animate={SHOWN} exit={{ opacity: 0, filter: "blur(8px)", y: -8 }} transition={reduce ? INSTANT : CARD_TRANSITION}>
                  <p className="art:font-medium art:text-muted-foreground art:text-xs">{story.label}</p>
                  <h3 className="art:mt-3 art:text-balance art:leading-[1.04] art:tracking-[-0.04em] art:text-xl art:font-medium">{story.title}</h3>
                  <p className="art:mt-4 art:max-w-lg art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{story.body}</p>
                </motion.div>
              </AnimatePresence>
            </div>
          </div>

          <div className="art:flex art:flex-col art:rounded-3xl art:border art:border-border/70 art:bg-background art:p-3 art:@min-[640px]/artemis:p-4">
            <fieldset className="art:flex art:min-w-0 art:flex-1 art:flex-col art:border-0 art:p-0">
              <legend className="art:sr-only">Choose a use case</legend>
              {STORIES.map((s) => (<StoryOption key={s.id} story={s} active={s.id === story.id} onSelect={() => setActiveId(s.id)}/>))}
            </fieldset>
            <ArtemisButtonLink href="#" variant="secondary" className="art:mt-3 art:w-full art:justify-between art:h-9">
              Explore every story
              <ArrowRight className="art:size-4" aria-hidden="true"/>
            </ArtemisButtonLink>
          </div>
        </div>
      </div>
    </section>);
}

