import { Compass, HeartHandshake, Lightbulb, type LucideIcon } from "lucide-react";
export type SceneId = "direction" | "trust" | "idea";
export interface UseCaseStory {
    id: SceneId;
    icon: LucideIcon;
    label: string;
    summary: string;
    title: string;
    body: string;
}
export const STORIES: UseCaseStory[] = [
    {
        id: "direction",
        icon: Compass,
        label: "Finding the next direction",
        summary: "From scattered instinct to shared conviction",
        title: "Turn an early signal into something the team can believe in",
        body: "Hold the customer need, the open questions, and the strongest idea together until a clear direction begins to emerge.",
    },
    {
        id: "trust",
        icon: HeartHandshake,
        label: "Growing customer trust",
        summary: "Every conversation continues the last one",
        title: "Make every response feel connected to the person behind it",
        body: "Keep the full relationship visible so each answer can feel thoughtful, timely, and consistent with what came before.",
    },
    {
        id: "idea",
        icon: Lightbulb,
        label: "Protecting the big idea",
        summary: "The final release still feels like the first idea",
        title: "Carry the original intent through feedback, edits, and launch",
        body: "Give every collaborator the same understanding of what makes the work matter, even as the details continue to change.",
